import { test, expect } from '@playwright/test';

test.describe('Column Sort Direction Indication', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display correct sort direction arrow icon for each column', async ({ page }) => {
    // Verify initial state with no sort applied
    const sortArrow = page.getByRole('button', { name: /sort/i });
    await expect(sortArrow).toBeVisible();

    // Verify arrow icons are not visible initially
    const descArrow = page.getByRole('img', { name: /desc/i });
    await expect(descArrow).not.toBeVisible();

    const ascArrow = page.getByRole('img', { name: /asc/i });
    await expect(ascArrow).not.toBeVisible();

    // Click the first column to sort by it
    const firstColumn = page.getByRole('columnheader', { name: /first name/i });
    await firstColumn.click();

    // Verify descending arrow appears for the first column
    await expect(descArrow).toBeVisible();

    // Verify ascending arrow disappears for the first column
    await expect(ascArrow).not.toBeVisible();

    // Verify ascending arrow appears for the second column
    const secondColumn = page.getByRole('columnheader', { name: /last name/i });
    await secondColumn.click();

    await expect(ascArrow).toBeVisible();
    await expect(descArrow).not.toBeVisible();

    // Verify descending arrow appears for the second column
    await expect(descArrow).toBeVisible();

    // Verify ascending arrow disappears for the second column
    await expect(ascArrow).not.toBeVisible();

    // Verify arrow icons are not visible for other columns
    const thirdColumn = page.getByRole('columnheader', { name: /email/i });
    await thirdColumn.click();

    await expect(ascArrow).not.toBeVisible();
    await expect(descArrow).not.toBeVisible();
  });

  test('should update sort direction when clicking the same column again', async ({ page }) => {
    // Click the first column to sort by it
    const firstColumn = page.getByRole('columnheader', { name: /first name/i });
    await firstColumn.click();

    // Verify descending arrow appears for the first column
    const descArrow = page.getByRole('img', { name: /desc/i });
    await expect(descArrow).toBeVisible();

    // Click the first column again to toggle sort direction
    await firstColumn.click();

    // Verify ascending arrow appears for the first column
    await expect(ascArrow).toBeVisible();

    // Verify descending arrow disappears for the first column
    await expect(descArrow).not.toBeVisible();

    // Verify ascending arrow disappears for the second column
    const secondColumn = page.getByRole('columnheader', { name: /last name/i });
    await secondColumn.click();

    await expect(ascArrow).not.toBeVisible();

    // Verify descending arrow appears for the second column
    await expect(descArrow).toBeVisible();

    // Verify ascending arrow disappears for the second column
    await expect(ascArrow).not.toBeVisible();

    // Verify arrow icons are not visible for other columns
    const thirdColumn = page.getByRole('columnheader', { name: /email/i });
    await thirdColumn.click();

    await expect(ascArrow).not.toBeVisible();
    await expect(descArrow).not.toBeVisible();
  });
});
